INSERT INTO tour_itineraries (id, tour_id, day_number, title, description, created_at, updated_at) VALUES ('a2000000-0000-0000-0000-000000000001', 'a1000000-0000-0000-0000-000000000001', 1, 'Ngày 1: Đón khách và Bắt đầu hành trình kỳ thú', 'Hướng dẫn viên đưa đoàn đi tham quan các di tích lịch sử nổi tiếng. Dùng bữa trưa tại nhà hàng với các món hải sản tươi sống. Trải nghiệm cáp treo ngắm toàn cảnh thành phố từ trên cao. Tự do nghỉ ngơi tại khách sạn, chuẩn bị cho ngày tiếp theo.', NOW(), NOW());
INSERT INTO tour_itineraries (id, tour_id, day_number, title, description, created_at, updated_at) VALUES ('a2000000-0000-0000-0000-000000000002', 'a1000000-0000-0000-0000-000000000001', 2, 'Ngày 2 - Hành trình khám phá đầy cảm xúc', 'Quý khách tự do tắm biển và dạo chơi trên bãi cát trắng mịn. Thưởng thức ẩm thực truyền thống, sau đó về nhận phòng khách sạn nghỉ ngơi. Ghé thăm làng nghề truyền thống, tìm hiểu văn hóa bản địa. Trải nghiệm thưởng thức show diễn nghệ thuật thực cảnh hoành tráng.', NOW(), NOW());
INSERT INTO tour_itineraries (id, tour_id, day_number, title, description, created_at, updated_at) VALUES ('a2000000-0000-0000-0000-000000000003', 'a1000000-0000-0000-0000-000000000001', 3, 'Ngày 3: Trải nghiệm cuối cùng & Chào tạm biệt', 'Hướng dẫn viên đưa đoàn đi tham quan các di tích lịch sử nổi tiếng. Ăn trưa buffet tại nhà hàng chuẩn 4 sao với thực đơn phong phú. Buổi chiều, xe và hướng dẫn viên đưa đoàn ra sân bay/điểm hẹn ban đầu. Kết thúc chương trình tour, chào tạm biệt và hẹn gặp lại Quý khách trong những hành trình tiếp theo.', NOW(), NOW());
INSERT INTO tour_itineraries (id, tour_id, day_number, title, description, created_at, updated_at) VALUES ('a2000000-0000-0000-0000-000000000004', 'a1000000-0000-0000-0000-000000000002', 1, 'Ngày 1: Đón khách và Bắt đầu hành trình kỳ thú', 'Quý khách tự do tắm biển và dạo chơi trên bãi cát trắng mịn. Ăn trưa buffet tại nhà hàng chuẩn 4 sao với thực đơn phong phú. Tự do khám phá các khu mua sắm sầm uất và mua quà lưu niệm. Trải nghiệm thưởng thức show diễn nghệ thuật thực cảnh hoành tráng.', NOW(), NOW());
INSERT INTO tour_itineraries (id, tour_id, day_number, title, description, created_at, updated_at) VALUES ('a2000000-0000-0000-0000-000000000005', 'a1000000-0000-0000-0000-000000000002', 2, 'Ngày 2: Trải nghiệm cuối cùng & Chào tạm biệt', 'Quý khách tự do tắm biển và dạo chơi trên bãi cát trắng mịn. Thưởng thức ẩm thực truyền thống, sau đó về nhận phòng khách sạn nghỉ ngơi. Buổi chiều, xe và hướng dẫn viên đưa đoàn ra sân bay/điểm hẹn ban đầu. Kết thúc chương trình tour, chào tạm biệt và hẹn gặp lại Quý khách trong những hành trình tiếp theo.', NOW(), NOW());
INSERT INTO tour_itineraries (id, tour_id, day_number, title, description, created_at, updated_at) VALUES ('a2000000-0000-0000-0000-000000000006', 'a1000000-0000-0000-0000-000000000003', 1, 'Ngày 1: Đón khách và Bắt đầu hành trình kỳ thú', 'Đoàn tập trung tại điểm hẹn, khởi hành bắt đầu chuyến đi. Thưởng thức ẩm thực truyền thống, sau đó về nhận phòng khách sạn nghỉ ngơi. Trải nghiệm cáp treo ngắm toàn cảnh thành phố từ trên cao. Buổi tối, quý khách dùng bữa tối ấm cúng. Sau đó tự do dạo phố, khám phá chợ đêm.', NOW(), NOW());
INSERT INTO tour_itineraries (id, tour_id, day_number, title, description, created_at, updated_at) VALUES ('a2000000-0000-0000-0000-000000000007', 'a1000000-0000-0000-0000-000000000003', 2, 'Ngày 2: Trải nghiệm cuối cùng & Chào tạm biệt', 'Đón bình minh tại khu du lịch, thưởng thức bữa sáng đặc sản địa phương. Nghỉ ngơi và dùng bữa trưa tại khu sinh thái mát mẻ. Buổi chiều, xe và hướng dẫn viên đưa đoàn ra sân bay/điểm hẹn ban đầu. Kết thúc chương trình tour, chào tạm biệt và hẹn gặp lại Quý khách trong những hành trình tiếp theo.', NOW(), NOW());
INSERT INTO tour_itineraries (id, tour_id, day_number, title, description, created_at, updated_at) VALUES ('a2000000-0000-0000-0000-000000000008', 'a1000000-0000-0000-0000-000000000004', 1, 'Ngày 1: Đón khách và Bắt đầu hành trình kỳ thú', 'Hướng dẫn viên đưa đoàn đi tham quan các di tích lịch sử nổi tiếng. Thưởng thức ẩm thực truyền thống, sau đó về nhận phòng khách sạn nghỉ ngơi. Ghé thăm làng nghề truyền thống, tìm hiểu văn hóa bản địa. Giao lưu văn nghệ, đốt lửa trại và thưởng thức rượu cần cùng đồng bào.', NOW(), NOW());
