INSERT INTO tour_itineraries (id, tour_id, day_number, title, description, created_at, updated_at) VALUES ('a2000000-0000-0000-0000-000000000021', 'a1000000-0000-0000-0000-000000000007', 3, 'Ngày 3: Trải nghiệm cuối cùng & Chào tạm biệt', 'Đoàn tập trung tại điểm hẹn, khởi hành bắt đầu chuyến đi. Nghỉ ngơi và dùng bữa trưa tại khu sinh thái mát mẻ. Buổi chiều, xe và hướng dẫn viên đưa đoàn ra sân bay/điểm hẹn ban đầu. Kết thúc chương trình tour, chào tạm biệt và hẹn gặp lại Quý khách trong những hành trình tiếp theo.', NOW(), NOW());
INSERT INTO tour_itineraries (id, tour_id, day_number, title, description, created_at, updated_at) VALUES ('a2000000-0000-0000-0000-000000000022', 'a1000000-0000-0000-0000-000000000008', 1, 'Ngày 1: Đón khách và Bắt đầu hành trình kỳ thú', 'Trải nghiệm ngồi thuyền ngắm cảnh quan thiên nhiên hùng vĩ. Thưởng thức ẩm thực truyền thống, sau đó về nhận phòng khách sạn nghỉ ngơi. Ghé thăm làng nghề truyền thống, tìm hiểu văn hóa bản địa. Trải nghiệm thưởng thức show diễn nghệ thuật thực cảnh hoành tráng.', NOW(), NOW());
INSERT INTO tour_itineraries (id, tour_id, day_number, title, description, created_at, updated_at) VALUES ('a2000000-0000-0000-0000-000000000023', 'a1000000-0000-0000-0000-000000000008', 2, 'Ngày 2 - Hành trình khám phá đầy cảm xúc', 'Quý khách tự do tắm biển và dạo chơi trên bãi cát trắng mịn. Nghỉ ngơi và dùng bữa trưa tại khu sinh thái mát mẻ. Trải nghiệm cáp treo ngắm toàn cảnh thành phố từ trên cao. Tự do nghỉ ngơi tại khách sạn, chuẩn bị cho ngày tiếp theo.', NOW(), NOW());
INSERT INTO tour_itineraries (id, tour_id, day_number, title, description, created_at, updated_at) VALUES ('a2000000-0000-0000-0000-000000000024', 'a1000000-0000-0000-0000-000000000008', 3, 'Ngày 3: Trải nghiệm cuối cùng & Chào tạm biệt', 'Đoàn tập trung tại điểm hẹn, khởi hành bắt đầu chuyến đi. Dùng bữa trưa tại nhà hàng với các món hải sản tươi sống. Buổi chiều, xe và hướng dẫn viên đưa đoàn ra sân bay/điểm hẹn ban đầu. Kết thúc chương trình tour, chào tạm biệt và hẹn gặp lại Quý khách trong những hành trình tiếp theo.', NOW(), NOW());
