INSERT INTO tour_itineraries (id, tour_id, day_number, title, description, created_at, updated_at) VALUES ('a2000000-0000-0000-0000-000000000048', 'a1000000-0000-0000-0000-000000000017', 1, 'Ngày 1: Đón khách và Bắt đầu hành trình kỳ thú', 'Quý khách tự do tắm biển và dạo chơi trên bãi cát trắng mịn. Nghỉ ngơi và dùng bữa trưa tại khu sinh thái mát mẻ. Buổi chiều, đoàn tiếp tục hành trình đến với các danh lam thắng cảnh. Tham gia các trò chơi vận động giải trí. Giao lưu văn nghệ, đốt lửa trại và thưởng thức rượu cần cùng đồng bào.', NOW(), NOW());
INSERT INTO tour_itineraries (id, tour_id, day_number, title, description, created_at, updated_at) VALUES ('a2000000-0000-0000-0000-000000000049', 'a1000000-0000-0000-0000-000000000017', 2, 'Ngày 2: Trải nghiệm cuối cùng & Chào tạm biệt', 'Quý khách tự do tắm biển và dạo chơi trên bãi cát trắng mịn. Nghỉ ngơi và dùng bữa trưa tại khu sinh thái mát mẻ. Buổi chiều, xe và hướng dẫn viên đưa đoàn ra sân bay/điểm hẹn ban đầu. Kết thúc chương trình tour, chào tạm biệt và hẹn gặp lại Quý khách trong những hành trình tiếp theo.', NOW(), NOW());
INSERT INTO tour_itineraries (id, tour_id, day_number, title, description, created_at, updated_at) VALUES ('a2000000-0000-0000-0000-000000000050', 'a1000000-0000-0000-0000-000000000018', 1, 'Ngày 1: Đón khách và Bắt đầu hành trình kỳ thú', 'Đoàn tập trung tại điểm hẹn, khởi hành bắt đầu chuyến đi. Nghỉ ngơi và dùng bữa trưa tại khu sinh thái mát mẻ. Ghé thăm làng nghề truyền thống, tìm hiểu văn hóa bản địa. Tự do nghỉ ngơi tại khách sạn, chuẩn bị cho ngày tiếp theo.', NOW(), NOW());
INSERT INTO tour_itineraries (id, tour_id, day_number, title, description, created_at, updated_at) VALUES ('a2000000-0000-0000-0000-000000000051', 'a1000000-0000-0000-0000-000000000018', 2, 'Ngày 2 - Hành trình khám phá đầy cảm xúc', 'Đón bình minh tại khu du lịch, thưởng thức bữa sáng đặc sản địa phương. Dùng bữa trưa tại nhà hàng với các món hải sản tươi sống. Ghé thăm làng nghề truyền thống, tìm hiểu văn hóa bản địa. Trải nghiệm thưởng thức show diễn nghệ thuật thực cảnh hoành tráng.', NOW(), NOW());
INSERT INTO tour_itineraries (id, tour_id, day_number, title, description, created_at, updated_at) VALUES ('a2000000-0000-0000-0000-000000000052', 'a1000000-0000-0000-0000-000000000018', 3, 'Ngày 3: Trải nghiệm cuối cùng & Chào tạm biệt', 'Quý khách tự do tắm biển và dạo chơi trên bãi cát trắng mịn. Nghỉ ngơi và dùng bữa trưa tại khu sinh thái mát mẻ. Buổi chiều, xe và hướng dẫn viên đưa đoàn ra sân bay/điểm hẹn ban đầu. Kết thúc chương trình tour, chào tạm biệt và hẹn gặp lại Quý khách trong những hành trình tiếp theo.', NOW(), NOW());
INSERT INTO tour_itineraries (id, tour_id, day_number, title, description, created_at, updated_at) VALUES ('a2000000-0000-0000-0000-000000000053', 'a1000000-0000-0000-0000-000000000019', 1, 'Ngày 1: Đón khách và Bắt đầu hành trình kỳ thú', 'Đoàn tập trung tại điểm hẹn, khởi hành bắt đầu chuyến đi. Nghỉ ngơi và dùng bữa trưa tại khu sinh thái mát mẻ. Trải nghiệm cáp treo ngắm toàn cảnh thành phố từ trên cao. Giao lưu văn nghệ, đốt lửa trại và thưởng thức rượu cần cùng đồng bào.', NOW(), NOW());
INSERT INTO tour_itineraries (id, tour_id, day_number, title, description, created_at, updated_at) VALUES ('a2000000-0000-0000-0000-000000000054', 'a1000000-0000-0000-0000-000000000019', 2, 'Ngày 2: Trải nghiệm cuối cùng & Chào tạm biệt', 'Hướng dẫn viên đưa đoàn đi tham quan các di tích lịch sử nổi tiếng. Nghỉ ngơi và dùng bữa trưa tại khu sinh thái mát mẻ. Buổi chiều, xe và hướng dẫn viên đưa đoàn ra sân bay/điểm hẹn ban đầu. Kết thúc chương trình tour, chào tạm biệt và hẹn gặp lại Quý khách trong những hành trình tiếp theo.', NOW(), NOW());
INSERT INTO tour_itineraries (id, tour_id, day_number, title, description, created_at, updated_at) VALUES ('a2000000-0000-0000-0000-000000000055', 'a1000000-0000-0000-0000-000000000020', 1, 'Ngày 1: Đón khách và Bắt đầu hành trình kỳ thú', 'Đoàn tập trung tại điểm hẹn, khởi hành bắt đầu chuyến đi. Ăn trưa buffet tại nhà hàng chuẩn 4 sao với thực đơn phong phú. Buổi chiều, đoàn tiếp tục hành trình đến với các danh lam thắng cảnh. Tham gia các trò chơi vận động giải trí. Buổi tối, quý khách dùng bữa tối ấm cúng. Sau đó tự do dạo phố, khám phá chợ đêm.', NOW(), NOW());
