INSERT INTO tour_itineraries (id, tour_id, day_number, title, description, created_at, updated_at) VALUES ('a2000000-0000-0000-0000-000000000075', 'a1000000-0000-0000-0000-000000000024', 11, 'Ngày 11 - Hành trình khám phá đầy cảm xúc', 'Trải nghiệm ngồi thuyền ngắm cảnh quan thiên nhiên hùng vĩ. Nghỉ ngơi và dùng bữa trưa tại khu sinh thái mát mẻ. Buổi chiều, đoàn tiếp tục hành trình đến với các danh lam thắng cảnh. Tham gia các trò chơi vận động giải trí. Giao lưu văn nghệ, đốt lửa trại và thưởng thức rượu cần cùng đồng bào.', NOW(), NOW());
INSERT INTO tour_itineraries (id, tour_id, day_number, title, description, created_at, updated_at) VALUES ('a2000000-0000-0000-0000-000000000076', 'a1000000-0000-0000-0000-000000000024', 12, 'Ngày 12 - Hành trình khám phá đầy cảm xúc', 'Hướng dẫn viên đưa đoàn đi tham quan các di tích lịch sử nổi tiếng. Nghỉ ngơi và dùng bữa trưa tại khu sinh thái mát mẻ. Buổi chiều, đoàn tiếp tục hành trình đến với các danh lam thắng cảnh. Tham gia các trò chơi vận động giải trí. Trải nghiệm thưởng thức show diễn nghệ thuật thực cảnh hoành tráng.', NOW(), NOW());
INSERT INTO tour_itineraries (id, tour_id, day_number, title, description, created_at, updated_at) VALUES ('a2000000-0000-0000-0000-000000000077', 'a1000000-0000-0000-0000-000000000024', 13, 'Ngày 13 - Hành trình khám phá đầy cảm xúc', 'Trải nghiệm ngồi thuyền ngắm cảnh quan thiên nhiên hùng vĩ. Nghỉ ngơi và dùng bữa trưa tại khu sinh thái mát mẻ. Trải nghiệm cáp treo ngắm toàn cảnh thành phố từ trên cao. Giao lưu văn nghệ, đốt lửa trại và thưởng thức rượu cần cùng đồng bào.', NOW(), NOW());
INSERT INTO tour_itineraries (id, tour_id, day_number, title, description, created_at, updated_at) VALUES ('a2000000-0000-0000-0000-000000000078', 'a1000000-0000-0000-0000-000000000024', 14, 'Ngày 14 - Hành trình khám phá đầy cảm xúc', 'Hướng dẫn viên đưa đoàn đi tham quan các di tích lịch sử nổi tiếng. Thưởng thức ẩm thực truyền thống, sau đó về nhận phòng khách sạn nghỉ ngơi. Buổi chiều, đoàn tiếp tục hành trình đến với các danh lam thắng cảnh. Tham gia các trò chơi vận động giải trí. Giao lưu văn nghệ, đốt lửa trại và thưởng thức rượu cần cùng đồng bào.', NOW(), NOW());
INSERT INTO tour_itineraries (id, tour_id, day_number, title, description, created_at, updated_at) VALUES ('a2000000-0000-0000-0000-000000000079', 'a1000000-0000-0000-0000-000000000024', 15, 'Ngày 15: Trải nghiệm cuối cùng & Chào tạm biệt', 'Đoàn tập trung tại điểm hẹn, khởi hành bắt đầu chuyến đi. Nghỉ ngơi và dùng bữa trưa tại khu sinh thái mát mẻ. Buổi chiều, xe và hướng dẫn viên đưa đoàn ra sân bay/điểm hẹn ban đầu. Kết thúc chương trình tour, chào tạm biệt và hẹn gặp lại Quý khách trong những hành trình tiếp theo.', NOW(), NOW());
INSERT INTO tour_itineraries (id, tour_id, day_number, title, description, created_at, updated_at) VALUES ('a2000000-0000-0000-0000-000000000080', 'a1000000-0000-0000-0000-000000000025', 1, 'Ngày 1: Đón khách và Bắt đầu hành trình kỳ thú', 'Hướng dẫn viên đưa đoàn đi tham quan các di tích lịch sử nổi tiếng. Dùng bữa trưa tại nhà hàng với các món hải sản tươi sống. Tự do khám phá các khu mua sắm sầm uất và mua quà lưu niệm. Trải nghiệm thưởng thức show diễn nghệ thuật thực cảnh hoành tráng.', NOW(), NOW());
