INSERT INTO tour_itineraries (id, tour_id, day_number, title, description, created_at, updated_at) VALUES ('a2000000-0000-0000-0000-000000000082', 'a1000000-0000-0000-0000-000000000026', 1, 'Ngày 1: Đón khách và Bắt đầu hành trình kỳ thú', 'Đón bình minh tại khu du lịch, thưởng thức bữa sáng đặc sản địa phương. Nghỉ ngơi và dùng bữa trưa tại khu sinh thái mát mẻ. Tự do khám phá các khu mua sắm sầm uất và mua quà lưu niệm. Trải nghiệm thưởng thức show diễn nghệ thuật thực cảnh hoành tráng.', NOW(), NOW());
INSERT INTO tour_itineraries (id, tour_id, day_number, title, description, created_at, updated_at) VALUES ('a2000000-0000-0000-0000-000000000083', 'a1000000-0000-0000-0000-000000000026', 2, 'Ngày 2 - Hành trình khám phá đầy cảm xúc', 'Hướng dẫn viên đưa đoàn đi tham quan các di tích lịch sử nổi tiếng. Nghỉ ngơi và dùng bữa trưa tại khu sinh thái mát mẻ. Tự do khám phá các khu mua sắm sầm uất và mua quà lưu niệm. Tự do nghỉ ngơi tại khách sạn, chuẩn bị cho ngày tiếp theo.', NOW(), NOW());
INSERT INTO tour_itineraries (id, tour_id, day_number, title, description, created_at, updated_at) VALUES ('a2000000-0000-0000-0000-000000000084', 'a1000000-0000-0000-0000-000000000026', 3, 'Ngày 3: Trải nghiệm cuối cùng & Chào tạm biệt', 'Hướng dẫn viên đưa đoàn đi tham quan các di tích lịch sử nổi tiếng. Nghỉ ngơi và dùng bữa trưa tại khu sinh thái mát mẻ. Buổi chiều, xe và hướng dẫn viên đưa đoàn ra sân bay/điểm hẹn ban đầu. Kết thúc chương trình tour, chào tạm biệt và hẹn gặp lại Quý khách trong những hành trình tiếp theo.', NOW(), NOW());
INSERT INTO tour_itineraries (id, tour_id, day_number, title, description, created_at, updated_at) VALUES ('a2000000-0000-0000-0000-000000000085', 'a1000000-0000-0000-0000-000000000027', 1, 'Ngày 1: Đón khách và Bắt đầu hành trình kỳ thú', 'Trải nghiệm ngồi thuyền ngắm cảnh quan thiên nhiên hùng vĩ. Nghỉ ngơi và dùng bữa trưa tại khu sinh thái mát mẻ. Trải nghiệm cáp treo ngắm toàn cảnh thành phố từ trên cao. Trải nghiệm thưởng thức show diễn nghệ thuật thực cảnh hoành tráng.', NOW(), NOW());
INSERT INTO tour_itineraries (id, tour_id, day_number, title, description, created_at, updated_at) VALUES ('a2000000-0000-0000-0000-000000000086', 'a1000000-0000-0000-0000-000000000027', 2, 'Ngày 2 - Hành trình khám phá đầy cảm xúc', 'Đón bình minh tại khu du lịch, thưởng thức bữa sáng đặc sản địa phương. Ăn trưa buffet tại nhà hàng chuẩn 4 sao với thực đơn phong phú. Ghé thăm làng nghề truyền thống, tìm hiểu văn hóa bản địa. Buổi tối, quý khách dùng bữa tối ấm cúng. Sau đó tự do dạo phố, khám phá chợ đêm.', NOW(), NOW());
